// Generates src/lib/commit-hash.generated.ts from the current git HEAD.
//
// Run before `bun run build` so the version badge shows the commit the
// bundle was actually built from (spec 55, window/version work):
//
//   node scripts/generate-commit-hash.mjs
//
// The generated file is committed so a fresh clone still builds; the
// script refreshes it at release time. When git is unavailable (a source
// export without .git) the hash falls back to "unknown" instead of
// failing the build. This script intentionally does NOT touch
// package.json or vite.config.ts — wire it into the release workflow's
// "Compile Frontend" step before `bun run build`, or a `prebuild`
// script, so the value is fresh on every release build.

import { execSync } from "node:child_process";
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";

const scriptDir = dirname(fileURLToPath(import.meta.url));
const repoRoot = join(scriptDir, "..");
const outputPath = join(repoRoot, "src", "lib", "commit-hash.generated.ts");

function resolveCommitHash() {
  try {
    const hash = execSync("git rev-parse --short HEAD", {
      cwd: repoRoot,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "ignore"],
    }).trim();

    if (hash.length > 0) {
      return hash;
    }
  } catch {
    // No git available — fall through to the unknown fallback.
  }

  return "unknown";
}

const commitHash = resolveCommitHash();
const content =
  `// GENERATED by scripts/generate-commit-hash.mjs — do not edit by hand.\n` +
  `// Refresh with: node scripts/generate-commit-hash.mjs\n` +
  `export const COMMIT_HASH = ${JSON.stringify(commitHash)};\n`;

writeFileSync(outputPath, content);
console.log(`commit-hash: ${commitHash} -> src/lib/commit-hash.generated.ts`);
